import unittest

from solution import coerce_optional_int


class CoerceOptionalIntTests(unittest.TestCase):
    def test_none_and_empty_tokens(self):
        for value in (None, "", "   \t", "none", "NONE", " Null ", "nUlL"):
            with self.subTest(value=value):
                self.assertIsNone(coerce_optional_int(value))

    def test_integer_inputs_include_zero_and_negatives(self):
        for value in (0, -1, 42):
            with self.subTest(value=value):
                self.assertEqual(coerce_optional_int(value), value)

    def test_valid_ascii_integer_strings(self):
        cases = {
            "0": 0,
            "+0": 0,
            "-0": 0,
            "  +0012  ": 12,
            "-0042": -42,
            "987": 987,
        }
        for text, expected in cases.items():
            with self.subTest(text=text):
                self.assertEqual(coerce_optional_int(text), expected)

    def test_invalid_strings(self):
        for value in ("+", "-", "1.0", "1 2", "0x10", "12a", "٣", "４", "+ 1"):
            with self.subTest(value=value), self.assertRaises(ValueError):
                coerce_optional_int(value)

    def test_booleans_and_other_types_raise_type_error(self):
        for value in (False, True, 1.5, [], {}, b"1"):
            with self.subTest(value=value), self.assertRaises(TypeError):
                coerce_optional_int(value)


if __name__ == "__main__":
    unittest.main()

